        slot,
        summary: None,
        returned: None,
    });
    let p = self.pending.as_mut().ok_or(error(Cause::Invariant))?;
    let summary = p.receipt.summary().ok_or(error(Cause::Invariant))?;
    p.summary = Some(summary);
    let (kind, generation, bits) =
